        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PREVIOUS_POLICY_DEDUCTIBLE end) as PREVIOUS_POLICY_DEDUCTIBLE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FIRST_POLICY_REFERENCE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then FIRST_POLICY_REFERENCE end)) as FIRST_POLICY_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PREVIOUS_INSURER_BRANCH_ADDRESS end) as PREVIOUS_INSURER_BRANCH_ADDRESS,
