                     then md5(upper(coalesce(cast(PREVIOUS_POLICY_EXPIRY_DATE as varchar), '') || '|' || coalesce(cast(PORTABILITY_REASON as varchar), '') || '|' || coalesce(cast(FIRST_POLICY_INCEPTION_DATE as varchar), '') || '|' || coalesce(cast(PREVIOUS_INSURER_ADDRESS as varchar), '') || '|' || coalesce(cast(PREVIOUS_POLICY_DEDUCTIBLE as varchar), '') || '|' || coalesce(cast(FIRST_POLICY_REFERENCE as varchar), '') || '|' || coalesce(cast(PREVIOUS_INSURER_BRANCH_ADDRESS as varchar), '') || '|' || coalesce(cast(PREVIOUS_POLICY_INCEPTION_DATE as varchar), '') || '|' || coalesce(cast(PREVIOUS_POLICY_START_DATE as varchar), '') || '|' || coalesce(cast(PORTED_CUMULATIVE_BONUS_AMOUNT as varchar), '') || '|' || coalesce(cast(FIRST_POLICY_NUMBER as varchar), '') || '|' || coalesce(cast(FIRST_ORIGINAL_POLICY_REFERENCE as varchar), '') || '|' || coalesce(cast(ORIGINATING_POLICY_NUMBER as varchar), '') || '|' || coalesce(cast(PREVIOUS_POLICY_DETAIL as varchar), '')))
